create table if not exists public.schoolpro_custom_requests(id uuid primary key default gen_random_uuid(),requester_user_id uuid references auth.users(id),school_id uuid references public.schoolpro_schools(id),school_name text not null,contact_name text not null,email text not null,phone text,existing_domain text,desired_domain text,logo_url text,primary_color text,secondary_color text,motto text,about_text text,requested_pages text[] not null default array['home','about','academics','admissions','facilities','gallery','news','leadership','contact','apply','result_checker','portal'],requested_modules text[] not null default '{}',package_interest text not null default 'custom',notes text,status text not null default 'submitted',quoted_amount numeric,quote_notes text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,approved_at timestamptz,provisioned_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.schoolpro_site_content(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,page_key text not null,section_key text not null,title text,body text,image_url text,metadata jsonb not null default '{}'::jsonb,is_published boolean not null default false,sort_order int not null default 0,updated_at timestamptz not null default now(),unique(school_id,page_key,section_key));
create table if not exists public.schoolpro_site_gallery(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,title text,image_url text not null,caption text,is_published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.schoolpro_site_news(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,title text not null,slug text not null,excerpt text,body text,cover_image_url text,published_at timestamptz,is_published boolean not null default false,created_at timestamptz not null default now(),unique(school_id,slug));
alter table public.schoolpro_custom_requests enable row level security;alter table public.schoolpro_site_content enable row level security;alter table public.schoolpro_site_gallery enable row level security;alter table public.schoolpro_site_news enable row level security;
grant select,insert,update on public.schoolpro_custom_requests to authenticated;grant select,insert,update,delete on public.schoolpro_site_content,public.schoolpro_site_gallery,public.schoolpro_site_news to authenticated;
create policy "own custom requests" on public.schoolpro_custom_requests for select to authenticated using(requester_user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role::text='super_admin'));
create policy "submit custom request" on public.schoolpro_custom_requests for insert to authenticated with check(requester_user_id=(select auth.uid()));
create policy "superadmin custom request update" on public.schoolpro_custom_requests for update to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role::text='super_admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role::text='super_admin'));
